import FormData from "form-data"; // form-data v4.0.1
import Mailgun from "mailgun.js"; // mailgun.js v11.1.0

async function sendSimpleMessage() {
  const mailgun = new Mailgun(FormData);
  const mg = mailgun.client({
    username: "api",
    key: process.env.API_KEY || "API_KEY",
    // When you have an EU-domain, you must specify the endpoint:
    // url: "https://api.eu.mailgun.net"
  });
  try {
    const data = await mg.messages.create("spirit.andyflinn.com", {
      from: "Mailgun Sandbox <postmaster@spirit.andyflinn.com>",
      to: ["ANDREAS THUT <countinn@gmail.com>"],
      subject: "Hello ANDREAS THUT",
      text: "Congratulations ANDREAS THUT, you just sent an email with Mailgun! You are truly awesome!",
    });

    console.log(data); // logs response data
  } catch (error) {
    console.log(error); //logs any error
  }
}

In the box as your flow. Yes, I reused the login cycle for onboarding; your one-field page does that cleanly.
What I would build with it, as statements:
- the page remembers which email a code was sent to with a short cookie, since the user then types only the code;
- the long session is kept with the member as a hash and an expiry, so a relay restart does not log people out;
- Natter takes the pasted email:token where a relay invite is entered today.
One thing must be decided first: at claim, the invite label becomes the member public label, so an email label would be published in the relay roll. What should a member public label be when the invite is an email?
